package dev.kats.smsbridge;
import java.security.*;
import java.security.spec.*;
import java.math.BigInteger;
public class WebPushCheck {
 public static void main(String[] args)throws Exception{
  KeyPair recipient=WebPush.pair(),vapid=WebPush.pair();byte[] auth=WebPush.random(16);byte[] encrypted=WebPush.encrypt(WebPush.point(recipient.getPublic()),auth,WebPush.utf("Тест BANK 900 🔐"));
  System.out.println(WebPush.b64(recipient.getPrivate().getEncoded()));System.out.println(WebPush.b64(WebPush.point(recipient.getPublic())));System.out.println(WebPush.b64(auth));System.out.println(WebPush.b64(encrypted));
  System.out.println(WebPush.authorization(WebPush.endpoint("https://web.push.apple.com/test"),vapid.getPrivate(),vapid.getPublic(),1800000000));
  // RFC 8291 section 5 published known-answer vector (not generated by our code).
  String asPub="BP4z9KsN6nGRTbVYI_c7VJSPQTBtkgcy27mlmlMoZIIgDll6e3vCYLocInmYWAmS6TlzAC8wEqKK6PBru3jl7A8";
  PublicKey serverPub=WebPush.publicKey(WebPush.un64(asPub));
  PrivateKey serverPriv=KeyFactory.getInstance("EC").generatePrivate(new ECPrivateKeySpec(new BigInteger(1,WebPush.un64("yfWPiYE-n46HLnH0KqZOF1fJJU3MYrct3AELtAQ-oRw")),((java.security.interfaces.ECPublicKey)serverPub).getParams()));
  byte[] vector=WebPush.encrypt(WebPush.un64("BCVxsr7N_eNgVRqvHtD0zTZsEc6-VV-JvLexhqUzORcxaOzi6-AYWXvTBHm4bjyPjs7Vd8pZGH6SRpkNtoIAiw4"),WebPush.un64("BTBZMqHH6r4Tts7J_aSIgg"),WebPush.utf("When I grow up, I want to be a watermelon"),new KeyPair(serverPub,serverPriv),WebPush.un64("DGv6ra1nlYgDCS1FRnbzlw"));
  if(!WebPush.b64(vector).equals("DGv6ra1nlYgDCS1FRnbzlwAAEABBBP4z9KsN6nGRTbVYI_c7VJSPQTBtkgcy27mlmlMoZIIgDll6e3vCYLocInmYWAmS6TlzAC8wEqKK6PBru3jl7A_yl95bQpu6cVPTpK4Mqgkf1CXztLVBSt2Ks3oZwbuwXPXLWyouBWLVWGNWQexSgSxsj_Qulcy4a-fN"))throw new AssertionError("RFC 8291 vector mismatch");
  for(String text:new String[]{"А🔐\\\"\n".repeat(1500),"日本語".repeat(2000),"x".repeat(8000)}){
   java.util.List<String> parts=WebPush.chunks(text);if(!String.join("",parts).equals(text))throw new AssertionError("chunk data loss");
   for(String part:parts){int escapedBytes=0;for(int i=0;i<part.length();){int cp=part.codePointAt(i);escapedBytes+=cp<32?6:cp=='"'||cp=='\\'?2:WebPush.utf(new String(Character.toChars(cp))).length;i+=Character.charCount(cp);}if(escapedBytes>2000)throw new AssertionError("chunk limit");}
  }
  for(String u:new String[]{"http://fcm.googleapis.com/test","https://127.0.0.1/x","https://fcm.googleapis.com.evil/x","https://x.push.apple.com:444/x","https://u@web.push.apple.com/x","https://web.push.apple.com/x#f"}){
   try{WebPush.endpoint(u);throw new AssertionError("endpoint allowed: "+u);}catch(IllegalArgumentException expected){}
  }
  byte[] offCurve=new byte[65];offCurve[0]=4;try{WebPush.publicKey(offCurve);throw new AssertionError("off curve");}catch(InvalidKeyException expected){}
  try{WebPush.encrypt(WebPush.point(recipient.getPublic()),auth,new byte[3994]);throw new AssertionError("oversize");}catch(InvalidKeyException expected){}
 }
}
